CREATE TABLE IF NOT EXISTS ministries (id TEXT PRIMARY KEY,church_id TEXT NOT NULL,name TEXT NOT NULL,leader_person_id TEXT,color TEXT NOT NULL DEFAULT '#285c45',status TEXT NOT NULL DEFAULT 'active',created_at INTEGER NOT NULL,FOREIGN KEY (church_id) REFERENCES churches(id),FOREIGN KEY (leader_person_id) REFERENCES people(id));
CREATE UNIQUE INDEX IF NOT EXISTS idx_ministry_name ON ministries(church_id,name);
CREATE TABLE IF NOT EXISTS ministry_roles (id TEXT PRIMARY KEY,church_id TEXT NOT NULL,ministry_id TEXT NOT NULL,name TEXT NOT NULL,required_count INTEGER NOT NULL DEFAULT 1,created_at INTEGER NOT NULL,FOREIGN KEY (church_id) REFERENCES churches(id),FOREIGN KEY (ministry_id) REFERENCES ministries(id) ON DELETE CASCADE);
CREATE UNIQUE INDEX IF NOT EXISTS idx_ministry_role_name ON ministry_roles(ministry_id,name);
CREATE TABLE IF NOT EXISTS schedules (id TEXT PRIMARY KEY,church_id TEXT NOT NULL,unit_id TEXT,event_id TEXT,title TEXT NOT NULL,starts_at INTEGER NOT NULL,arrival_at INTEGER,status TEXT NOT NULL DEFAULT 'draft',published_at INTEGER,created_by_user_id TEXT NOT NULL,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,FOREIGN KEY (church_id) REFERENCES churches(id),FOREIGN KEY (unit_id) REFERENCES church_units(id),FOREIGN KEY (event_id) REFERENCES events(id),FOREIGN KEY (created_by_user_id) REFERENCES church_users(id));
CREATE INDEX IF NOT EXISTS idx_schedules_church_start ON schedules(church_id,starts_at);
CREATE TABLE IF NOT EXISTS schedule_positions (id TEXT PRIMARY KEY,church_id TEXT NOT NULL,schedule_id TEXT NOT NULL,ministry_id TEXT NOT NULL,role_name TEXT NOT NULL,person_id TEXT,response_status TEXT NOT NULL DEFAULT 'open',responded_at INTEGER,note TEXT,created_at INTEGER NOT NULL,FOREIGN KEY (church_id) REFERENCES churches(id),FOREIGN KEY (schedule_id) REFERENCES schedules(id) ON DELETE CASCADE,FOREIGN KEY (ministry_id) REFERENCES ministries(id),FOREIGN KEY (person_id) REFERENCES people(id));
CREATE INDEX IF NOT EXISTS idx_schedule_positions_schedule ON schedule_positions(schedule_id,ministry_id);
CREATE TABLE IF NOT EXISTS volunteer_unavailability (id TEXT PRIMARY KEY,church_id TEXT NOT NULL,person_id TEXT NOT NULL,starts_at INTEGER NOT NULL,ends_at INTEGER NOT NULL,reason TEXT,created_at INTEGER NOT NULL,FOREIGN KEY (church_id) REFERENCES churches(id),FOREIGN KEY (person_id) REFERENCES people(id));
CREATE INDEX IF NOT EXISTS idx_volunteer_unavailability ON volunteer_unavailability(church_id,person_id,starts_at,ends_at);
PRAGMA optimize;
